<?php
namespace App\Livewire\Admin\Closures;use App\Enums\ClosureType;use App\Models\OfficeClosure;use Livewire\Component;
class Index extends Component{public string $title='';public string $type='holiday';public string $start_date='';public string $end_date='';public string $description='';public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isHR(),403);}public function save():void{$d=$this->validate(['title'=>['required','string','max:255'],'type'=>['required','in:'.implode(',',array_keys(ClosureType::getOptions()))],'start_date'=>['required','date'],'end_date'=>['required','date','after_or_equal:start_date'],'description'=>['nullable','string','max:2000']]);OfficeClosure::create($d+['created_by'=>auth()->id()]);$this->reset(['title','start_date','end_date','description']);session()->flash('success','Office closure added.');}public function delete(int $id):void{OfficeClosure::findOrFail($id)->delete();}public function render(){return view('livewire.admin.closures.index',['closures'=>OfficeClosure::with('creator')->orderByDesc('start_date')->get(),'types'=>ClosureType::getOptions()])->layout('components.layouts.admin',['title'=>'Office closures']);}}
